const rocket = {
  name: "Eagle",
  fuel: 50,
  // add the refuel(amount) and status() methods
  refuel(amount) {
    this.fuel = Math.min(this.fuel + amount, 100);
    return this.fuel;
  },
  status() {
    return `${this.name}: fuel ${this.fuel}`;
  },
};

console.log(rocket.refuel(30));
console.log(rocket.status());

