challenge.solution:
const crew = [
  { name: "Alex", role: "pilot", hours: 120 },
  { name: "Ada", role: "engineer", hours: 95 },
  { name: "Ben", role: "doctor", hours: 60 },
  { name: "Emma", role: "pilot", hours: 150 },
];

function crewReport(list) {
  let totalHours = 0;
  const pilots = [];
  let veteran = "";
  let maxHours = -1;
  for (const { name, role, hours } of list) {
    totalHours += hours;
    if (role === "pilot") {
      pilots.push(name);
    }
    if (hours > maxHours) {
      maxHours = hours;
      veteran = name;
    }
  }
  return { totalHours, pilots, veteran };
}

console.log(crewReport(crew));

