project_task.solution:
const player = {
  name: "Eagle",
  lives: 3,
  stars: 0,
  inventory: ["shield"],
  collectStar() {
    this.stars++;
    return this.stars;
  },
  hit() {
    if (this.lives > 0) {
      this.lives--;
    }
    return this.lives;
  },
  status() {
    return `${this.name} | Stars: ${this.stars} | Lives: ${this.lives}`;
  },
};

player.collectStar();
player.collectStar();
player.hit();
console.log(player.status());
